namespace { void Aid(DependencyObject const& e,wchar_t const* id){Microsoft::UI::Xaml::Automation::AutomationProperties::SetAutomationId(e,id);} hstring Tr(wchar_t const* key){try{auto value=Microsoft::Windows::ApplicationModel::Resources::ResourceLoader().GetString(key);return value.empty()?hstring(key):value;}catch(hresult_error const&){return hstring(key);}} }
TextBlock MainWindow::Text(hstring const& value,double size,bool bold){TextBlock t;t.Text(value);t.FontSize(size);if(bold)t.FontWeight(Windows::UI::Text::FontWeights::SemiBold());return t;}
MainWindow::MainWindow(){InitializeComponent();root_=Root();try{ExtendsContentIntoTitleBar(true);AppWindow().Resize({1100,720});}catch(hresult_error const&){}ShowAuth();}
void MainWindow::ShowAuth(){root_.Children().Clear();auto shell=Grid();shell.ColumnDefinitions().Append(ColumnDefinition());shell.ColumnDefinitions().Append(ColumnDefinition());shell.ColumnDefinitions().GetAt(0).Width(GridLengthHelper::FromPixels(410));auto hero=StackPanel();hero.Background(Application::Current().Resources().Lookup(box_value(L"TekPrimaryBrush")).as<Media::Brush>());hero.Padding({48});hero.Spacing(18);auto brand=Text(L"TEKtalk",48,true);brand.Foreground(Application::Current().Resources().Lookup(box_value(L"TekOnPrimaryBrush")).as<Media::Brush>());hero.Children().Append(brand);auto subtitle=Text(Tr(L"AuthHero"),20);subtitle.Foreground(Application::Current().Resources().Lookup(box_value(L"TekOnPrimaryBrush")).as<Media::Brush>());hero.Children().Append(subtitle);auto core=Text(core_.Available()?Tr(L"CoreConnected"):Tr(L"CoreFallback"),13,true);core.Foreground(Application::Current().Resources().Lookup(box_value(L"TekOnPrimaryBrush")).as<Media::Brush>());hero.Children().Append(core);Grid::SetColumn(hero,0);shell.Children().Append(hero);auto form=StackPanel();form.Padding({64});form.Spacing(12);form.MaxWidth(520);form.HorizontalAlignment(HorizontalAlignment::Stretch);form.Children().Append(Text(register_mode_?Tr(L"CreateAccount"):challenge_.empty()?Tr(L"SignIn"):Tr(L"VerifyDevice"),34,true));if(challenge_.empty()){phone_=TextBox();Aid(phone_,L"auth.phone");phone_.Header(box_value(Tr(L"PhoneE164")));phone_.Text(L"+84");form.Children().Append(phone_);if(register_mode_){name_=TextBox();Aid(name_,L"auth.name");name_.Header(box_value(Tr(L"DisplayName")));form.Children().Append(name_);}password_=PasswordBox();Aid(password_,L"auth.password");password_.Header(box_value(Tr(L"Password")));form.Children().Append(password_);if(register_mode_){question_=TextBox();Aid(question_,L"auth.question");question_.Header(box_value(Tr(L"SecurityQuestion")));question_.Text(Tr(L"DefaultSecurityQuestion"));form.Children().Append(question_);}}answer_=TextBox();Aid(answer_,L"auth.answer");answer_.Header(box_value(challenge_.empty()?Tr(L"SecurityAnswer"):Tr(L"AnswerChallenge")));if(register_mode_||!challenge_.empty())form.Children().Append(answer_);status_=Text(L"");form.Children().Append(status_);auto submit=Button();Aid(submit,L"auth.submit");submit.Content(box_value(challenge_.empty()?(register_mode_?Tr(L"Register"):Tr(L"SignIn")):Tr(L"VerifyDevice")));submit.HorizontalAlignment(HorizontalAlignment::Stretch);submit.Style(Application::Current().Resources().Lookup(box_value(L"AccentButtonStyle")).as<Style>());submit.Click([this](auto&&,auto&&){SubmitAuth();});form.Children().Append(submit);if(challenge_.empty()){auto toggle=Button();Aid(toggle,L"auth.toggle");toggle.Content(box_value(register_mode_?Tr(L"SwitchToLogin"):Tr(L"SwitchToRegister")));toggle.Click([this](auto&&,auto&&){register_mode_=!register_mode_;ShowAuth();});form.Children().Append(toggle);}Grid::SetColumn(form,1);shell.Children().Append(form);root_.Children().Append(shell);}
IAsyncAction MainWindow::SubmitAuth(){try{if(!challenge_.empty()){tokens_=tektalk::ApiClient::ParseTokens(co_await api_.Verify(challenge_,answer_.Text()));ShowHost();co_return;}if(!tektalk::ValidE164(phone_.Text().c_str())||!tektalk::ValidPassword(password_.Password().c_str())){status_.Text(Tr(L"InvalidCredentials"));co_return;}if(register_mode_){tokens_=tektalk::ApiClient::ParseTokens(co_await api_.Register(phone_.Text(),name_.Text(),password_.Password(),question_.Text(),answer_.Text()));ShowHost();}else{auto result=co_await api_.Login(phone_.Text(),password_.Password());if(result.HasKey(L"tokens")&&result.GetNamedValue(L"tokens").ValueType()==Windows::Data::Json::JsonValueType::Object){tokens_=tektalk::ApiClient::ParseTokens(result.GetNamedObject(L"tokens"));ShowHost();}else{challenge_=result.GetNamedString(L"challenge_id",L"");ShowAuth();status_.Text(result.GetNamedString(L"question",Tr(L"VerifyDevice")));}}}catch(hresult_error const&e){status_.Text(e.message());}}
void MainWindow::ShowHost(){root_.Children().Clear();auto nav=NavigationView();nav.IsBackButtonVisible(NavigationViewBackButtonVisible::Collapsed);nav.PaneTitle(L"TEKtalk");nav.PaneDisplayMode(NavigationViewPaneDisplayMode::Left);nav.IsPaneOpen(true);nav.OpenPaneLength(tektalk::design::SidebarWidth);nav.IsPaneToggleButtonVisible(false);nav.IsSettingsVisible(false);const std::pair<hstring,hstring> entries[]={{L"Message",Tr(L"Message")},{L"AI",L"AI"},{L"Me",Tr(L"Me")}};for(auto const& entry:entries){NavigationViewItem item;item.Content(box_value(entry.second));item.Tag(box_value(entry.first));FontIcon icon;icon.Glyph(entry.first==L"Message"?L"\uE8F2":entry.first==L"AI"?L"\uE945":L"\uE77B");item.Icon(icon);Microsoft::UI::Xaml::Automation::AutomationProperties::SetAutomationId(item,hstring(L"tab.")+entry.first);nav.MenuItems().Append(item);}nav.SelectionChanged([this](auto const&,NavigationViewSelectionChangedEventArgs const&e){auto item=e.SelectedItem().try_as<NavigationViewItem>();if(!item)return;auto tag=unbox_value<hstring>(item.Tag());if(tag==L"Message")ShowMessage();else if(tag==L"AI")ShowAI();else ShowMe();});root_.Children().Append(nav);nav.SelectedItem(nav.MenuItems().GetAt(0));}
void MainWindow::ShowMessage(){auto nav=root_.Children().GetAt(0).as<NavigationView>();auto panel=StackPanel();panel.Padding({28});panel.Spacing(10);panel.Children().Append(Text(Tr(L"Message"),32,true));conversation_=TextBox();Aid(conversation_,L"chat.conversation");conversation_.Header(box_value(L"Conversation UUID"));recipient_=TextBox();Aid(recipient_,L"chat.recipient");recipient_.Header(box_value(L"Recipient UUID"));panel.Children().Append(conversation_);panel.Children().Append(recipient_);auto sync=Button();Aid(sync,L"chat.sync");sync.Content(box_value(Tr(L"SyncHistory")));sync.Click([this](auto&&,auto&&){LoadMessages();});panel.Children().Append(sync);status_=Text(Tr(L"MessageStartHint"));panel.Children().Append(status_);messages_=ListView();messages_.Height(310);panel.Children().Append(messages_);auto row=StackPanel();row.Orientation(Orientation::Horizontal);row.Spacing(8);draft_=TextBox();Aid(draft_,L"chat.draft");draft_.PlaceholderText(Tr(L"ComposeMessage"));draft_.Width(500);row.Children().Append(draft_);auto send=Button();Aid(send,L"chat.send");send.Content(box_value(Tr(L"Send")));send.Click([this](auto&&,auto&&){SendMessage();});row.Children().Append(send);panel.Children().Append(row);nav.Content(panel);}
IAsyncAction MainWindow::LoadMessages(){if(!tokens_||!tektalk::LooksLikeUuid(conversation_.Text().c_str())){status_.Text(Tr(L"InvalidConversation"));co_return;}try{auto list=co_await api_.History(tokens_->access_token,conversation_.Text());messages_.Items().Clear();for(auto const&item:list){auto m=tektalk::ApiClient::ParseMessage(item.GetObject());messages_.Items().Append(box_value(m.body));}status_.Text(Tr(L"SyncedPrefix")+to_hstring(list.Size())+Tr(L"MessagesSuffix"));}catch(hresult_error const&e){status_.Text(e.message());}}
IAsyncAction MainWindow::SendMessage(){if(!tokens_||!tektalk::LooksLikeUuid(conversation_.Text().c_str())||!tektalk::LooksLikeUuid(recipient_.Text().c_str())||draft_.Text().empty()){status_.Text(Tr(L"InvalidMessage"));co_return;}try{auto m=tektalk::ApiClient::ParseMessage(co_await api_.Send(tokens_->access_token,conversation_.Text(),recipient_.Text(),draft_.Text()));messages_.Items().Append(box_value(m.body));draft_.Text(L"");status_.Text(Tr(L"SentSnowflake")+to_hstring(m.id));}catch(hresult_error const&e){status_.Text(e.message());}}
void MainWindow::ShowAI(){auto nav=root_.Children().GetAt(0).as<NavigationView>();auto panel=StackPanel();panel.Padding({42});panel.Spacing(12);panel.Children().Append(Text(L"TEK AI",32,true));panel.Children().Append(Text(Tr(L"AiDescription"),16));nav.Content(panel);}
void MainWindow::ShowMe(){auto nav=root_.Children().GetAt(0).as<NavigationView>();auto panel=StackPanel();panel.Padding({42});panel.Spacing(12);panel.Children().Append(Text(Tr(L"Me"),32,true));if(tokens_){panel.Children().Append(Text(Tr(L"User")+L": "+tokens_->user_id));panel.Children().Append(Text(Tr(L"Device")+L": "+tokens_->device_id));}panel.Children().Append(Text(core_.Available()?Tr(L"RustCoreConnectedLabel"):Tr(L"RustCoreFallbackLabel")));auto logout=Button();Aid(logout,L"auth.logout");logout.Content(box_value(Tr(L"SignOut")));logout.Click([this](auto&&,auto&&){tokens_.reset();challenge_=L"";register_mode_=false;ShowAuth();});panel.Children().Append(logout);nav.Content(panel);}
